import {Screen0 as Material} from "./0Describing the UI/section0"

export default function () {
  return (
    <>
    <Material/>
    </>
  );
}

function Check({content,yes}) {
  return <li>
    {content} {yes&&" wow"||"noo"}
  </li>
}

function UseMethod() {
  return <>
  {obj.map(x => {
   return <div
    style={x.style}
    >{x.content}</div>
      })}
  </>
}

const obj = [
  {style: {background: "yellowgreen"}, content: "anjass"},
  {style: {background: "aquamarine"}, content: "walawe"},
  {style: {background: "lightgreen"}, content: "ngawi land"},
]
